define(["jquery","core/ajax","core/notification"],function($,Ajax,Notification){var loading=false;var refresh=function(cmid){if(loading||document.hidden){return}loading=true;Ajax.call([{methodname:"mod_status_get_dashboard",args:{cmid:cmid}}])[0].then(function(result){$("[data-region='status-dashboard']").html(result.html)}).catch(function(error){Notification.exception(error)}).always(function(){loading=false})};return{init:function(cmid,interval){window.setInterval(function(){refresh(cmid)},interval||5e3)}}});